/********************************************** 
 * 함수명   : ins_search
 * 설명       : 채권 마스터  목록 조회한다.
 ***********************************************/
scwin.ins_search = function() {
    /**
     * SrM-000243255 
     */
    if (!scwin.checkSearchCondition()) {
        return false;
    }

    // 검색일 체크
    if ($c.stf.compareFromToDate2(edt_SISUDATE, edt_EISUDATE) == false) {
        return false;
    }

    // 검색일 체크
    if ($c.stf.compareFromToDate2(edt_SDATE, edt_EDATE) == false) {
        return false;
    }
    $c.stf.setObjectValue(ckb_BND_ISU_METHD_CD1, "N");
    $c.stf.setObjectValue(ckb_BND_ISU_METHD_CD2, "N");
    $c.stf.setObjectValue(ckb_BND_ISU_METHD_CD3, "N");
    dts_detail.removeAll();
    dts_callList.removeAll();
    dts_putList.removeAll();
    dts_CreditValuList.removeAll();
    dts_AsstList.removeAll();
    dts_BND_PAY_INT.removeAll();

    // 조회버튼 비활성.
    fn_SetDisableSelectBtn(btn_search, true);
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=STDCDSTKINFO_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.stdcdbnd.select.listStdCdBndInfoInquiry" + "&{P}STD_CD=" + txb_pSTD_CD.getValue() + "&{P}ISU_KOR_NM=" + txb_pISU_KOR_NM.getValue() + "&{P}ISUR_CD=" + txb_pISUR_CD.getValue() + "&{P}ACTIV_TP_CD=" + $c.stf.getObjectValue(cmb_pACTIV_YN) + "&{P}SISUDATE=" + edt_SISUDATE.getValue() + "&{P}EISUDATE=" + edt_EISUDATE.getValue() + "&{P}SDATE=" + edt_SDATE.getValue() + "&{P}EDATE=" + edt_EDATE.getValue();
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_Grid); // 그리드명을 표기

};


/********************************************** 
 * 함수명   : checkSearchCondition
 * 설명      : SrM-000243255  조회조건을 체크
 *                표준코드, 한글종목명, 발행기관코드에 값이 입력 안되었을 경우 
 *                날짜 조건은 필수로 입력되도록.. 날짜 입력가능 범위는 5년..
 ***********************************************/
scwin.checkSearchCondition = function() {
    var sStdCd = $c.stf.getObjectValue(txb_pSTD_CD);
    var sIsuKorNm = $c.stf.getObjectValue(txb_pISU_KOR_NM);
    var sIsurCd = $c.stf.getObjectValue(txb_pISUR_CD);
    var sIsuDateFrom = $c.stf.getObjectValue(edt_SISUDATE); //발행일(from)
    var sIsuDateTo = $c.stf.getObjectValue(edt_EISUDATE); //발행일(to)
    var sSDateFrom = $c.stf.getObjectValue(edt_SDATE); //코드부여일(from)
    var sSDateTo = $c.stf.getObjectValue(edt_EDATE); //코드부여일(to)

    if (sStdCd == "" && sIsuKorNm == "" && sIsurCd == "") {
        if (sIsuDateFrom == "" && sIsuDateTo == "" && sSDateFrom == "" && sSDateTo == "") {
            var msg = "조회조건을 최소 1개 이상 입력하세요.\n\n" + "[표준코드, 한글종목명, 발행기관명(코드)] 중 1개 이상의 조건을 입력하거나, \n" + "[발행일 또는 코드부여일]의 검색기간을 5년 이내로 입력하세요.";
            $c.win.alert(msg);
            return false;
        }

        // 발행일 체크
        if (sIsuDateFrom != "" && sIsuDateTo != "") {
            if (eval($c.ut.cGetPlusYear(sIsuDateFrom, 5)) < eval(sIsuDateTo)) {
                $c.win.alert("발행일의 검색기간은 5년 이내로 입력하세요.");
                edt_SISUDATE.focus();
                return false;
            }
        } else if (sIsuDateFrom != "" || sIsuDateTo != "") {
            $c.win.alert("발행일의 검색기간은 5년 이내로 입력하세요.");
            if (sIsuDateFrom == "") {
                edt_SISUDATE.focus();
            } else {
                edt_EISUDATE.focus();
            }
            return false;
        }

        // 코드부여일 체크
        if (sSDateFrom != "" && sSDateTo != "") {
            if (eval($c.ut.cGetPlusYear(sSDateFrom, 5)) < eval(sSDateTo)) {
                $c.win.alert("코드부여일의 검색기간은 5년 이내로 입력하세요.");
                edt_SDATE.focus();
                return false;
            }
        } else if (sSDateFrom != "" || sSDateTo != "") {
            $c.win.alert("코드부여일의 검색기간은 5년 이내로 입력하세요.");
            if (sSDateFrom == "") {
                edt_SDATE.focus();
            } else {
                edt_EDATE.focus();
            }
            return false;
        }
    }
    return true;
};


/********************************************** 
 * 함수명   : ins_detail
 * 설명       : 채권 마스터 상세 조회한다.
 ***********************************************/
scwin.ins_detail = function(STD_CD) {
    // 채권 마스터
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=BND_DETAIL_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.stdcdbnd.select.readStdCdBndInfoViewInfo" + "&{P}param01=" + STD_CD;
    dts_detail.DataID = encodeURI(url);
    dts_detail.reset();


    // 채권 CALL 마스터
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=BNDCALLEXERINFO_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.stdcdbnd.select.readStdCdBndCallExerInfoViewInfo" + "&{P}param01=" + STD_CD;
    dts_callList.DataID = encodeURI(url);
    dts_callList.reset();
    // 채권 PUT 마스터
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=BNDPUTEXERINFO_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.stdcdbnd.select.readStdCdBndPutExerInfoViewInfo" + "&{P}param01=" + STD_CD;
    dts_putList.DataID = encodeURI(url);
    dts_putList.reset();
    // 채권 신용평가 마스터
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=BNDCREDITVALUINFO_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.stdcdbnd.select.readStdCdBndCreditValuInfoViewInfo" + "&{P}param01=" + STD_CD;
    dts_CreditValuList.DataID = encodeURI(url);
    dts_CreditValuList.reset();
    // 채권 보유기관 마스터
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=BNDASSTINFO_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.stdcdbnd.select.readStdCdBndAsstInfoViewInfo" + "&{P}param01=" + STD_CD + "&{P}param02=" + STD_CD + "&{P}param03=" + STD_CD + "&{P}param04=" + STD_CD + "&{P}param05=" + STD_CD + "&{P}param06=" + STD_CD + "&{P}param07=" + STD_CD + "&{P}param08=" + STD_CD;
    dts_AsstList.DataID = encodeURI(url);
    dts_AsstList.reset();

    //채권지급이자 마스터
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=STDCDBNDPAYINTINFO_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.stdcdbnd.select.readStdCdBndPayIntInfoViewInfo" + "&{P}param01=" + STD_CD;
    dts_BND_PAY_INT.DataID = encodeURI(url);
    dts_BND_PAY_INT.reset();
};



/********************************************** 
 * 함수명   : fn_Change_cfi
 * 설명       : cfi 변경 설정
 ***********************************************/
scwin.fn_Change_cfi = function() {
    // Cfi의 콤보 박스를 변경할 경우....
    var cfi = "";
    cfi = "D";
    if ($c.stf.getObjectValue(cmb_cb_p_group) == "") {
        cfi += "_";
    } else {
        cfi += $c.stf.getObjectValue(cmb_cb_p_group);
    }
    if ($c.stf.getObjectValue(cmb_cb_p_attr_1) == "") {
        cfi += "_";
    } else {
        cfi += $c.stf.getObjectValue(cmb_cb_p_attr_1);
    }
    if ($c.stf.getObjectValue(cmb_cb_p_attr_2) == "") {
        cfi += "_";
    } else {
        cfi += $c.stf.getObjectValue(cmb_cb_p_attr_2);
    }
    if ($c.stf.getObjectValue(cmb_cb_p_attr_3) == "") {
        cfi += "_";
    } else {
        cfi += $c.stf.getObjectValue(cmb_cb_p_attr_3);
    }
    if ($c.stf.getObjectValue(cmb_cb_p_attr_4) == "") {
        cfi += "_";
    } else {
        cfi += $c.stf.getObjectValue(cmb_cb_p_attr_4);
    }
    txb_CFI_CD.setValue(cfi); // cfi 설정
    dts_detail.setCellData(dts_detail.getRowPosition(), "CFI_CD", cfi); // cfi 설정

};


/********************************************** 
 * 함수명   : fn_set_Change
 * 설명       :  상세 조회시 CFI 상세 설정 
 ***********************************************/
scwin.fn_set_Change = function(str_cfi) {
    if (str_cfi == "") return;
    $c.stf.setObjectValue(cmb_cb_p_group, str_cfi.substring(1, 2));
    $c.stf.setObjectValue(cmb_cb_p_attr_1, str_cfi.substring(2, 3));
    $c.stf.setObjectValue(cmb_cb_p_attr_2, str_cfi.substring(3, 4));
    $c.stf.setObjectValue(cmb_cb_p_attr_3, str_cfi.substring(4, 5));
    $c.stf.setObjectValue(cmb_cb_p_attr_4, str_cfi.substring(5, 6));
};


/********************************************** 
 * 함수명   : fn_COUPN_RT_DECSN_BAS_INT_CDChage
 * 설명       :  이자율결정기준금리 에 따른 기타기준금리 정의 
 ***********************************************/
scwin.fn_COUPN_RT_DECSN_BAS_INT_CDChage = function() {
    if ($c.stf.getObjectValue(cmb_COUPN_RT_DECSN_BAS_INT_CD) == "90") {
        txb_INT_RT_DECSN_MISC_BAS_INT_NM.setDisabled(false);
        txb_INT_RT_DECSN_MISC_BAS_INT_NM.ReadOnlyBackColor = 'white';
    } else {
        txb_INT_RT_DECSN_MISC_BAS_INT_NM.setDisabled(true);
        txb_INT_RT_DECSN_MISC_BAS_INT_NM.ReadOnlyBackColor = '#b9d4f7';
        txb_INT_RT_DECSN_MISC_BAS_INT_NM.setValue("");
    }
};


/********************************************** 
 * 함수명   : fn_setBndView
 * 설명       :  채권 상세화면을 정의한다.
 ***********************************************/
scwin.fn_setBndView = function(SIMSA_YN, LIST_STAT_CD) {
    if (LIST_STAT_CD == "N" && SIMSA_YN == "Y") {
        $c.win.alert(" 해당종목은 신규상장심사종목입니다. \n" + " 수정후에는 반드시 채권심사종목정보도 수정이 되도록 채권상장팀에 통보를 하셔야 됩니다.");
    } else if (LIST_STAT_CD == "Y") {
        //alert(" 상장채권은 수정할 수 없습니다 \n" + " 채권상장팀과 협의하시기 바랍니다");
        btn_modify.setDisabled(true);
        btn_modify.src = "../img/ins/btn_modify_d.gif";
        btn_delete.setDisabled(true);
        btn_delete.src = "../img/ins/btn_delete_d.gif";

        // alert 삭제 및 비밀번호 초기화도 제어 추가 20140116
        btn_clearPwd.setDisabled(true);
        btn_clearPwd.src = "../img/ins/btn_clearPwd_d.gif";
    } else {
        btn_modify.setDisabled(false);
        btn_modify.src = "../img/ins/btn_modify.gif";
        btn_delete.setDisabled(false);
        btn_delete.src = "../img/ins/btn_delete.gif";
        btn_clearPwd.setDisabled(false);
        btn_clearPwd.src = "../img/ins/btn_clearPwd.gif";
    }
};








/********************************************** 
 * 함수명   : fn_formCheck
 * 설명       : 폼을 체크한다.
 ***********************************************/
scwin.fn_formCheck = function(Typ) {
