        }
    }
    if ($c.stf.getObjectValue(cmb_NUSUAL_BND_TP_CD) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "특이채권유형"));
        cmb_NUSUAL_BND_TP_CD.focus();
        return false;
    }

    /*채권상장공시팀 장수진 사원 요청 - 주식관련(탭) 입력 체크 소스삭제
    if(getObjectValue(cmb_STK_REL_CORPBND_RGHT_TP_CD) != ""  && getObjectValue(cmb_NUSUAL_BND_TP_CD) != "2" ) {
    	alert(  "주식관련탭은 주식관련채권시에만 입력합니다. 주식관련사채항목을 확인바랍니다." );
    	tab_UsrInfo.ActiveIndex =5;	
    	cmb_NUSUAL_BND_TP_CD.focus();

    	txb_OBJ_ISU_CD.value = "";
    	txb_OBJ_ISU_NM.value = "";
    	return false;
    } 	*/

    if ($c.stf.getObjectValue(cmb_INT_PAY_METHD_CD) == "" || $c.stf.getObjectValue(cmb_INT_PAY_METHD_CD).substring(0, 1) == "1") {
        if ($c.stf.getObjectValue(txb_INT_RT_DECSN_MISC_BAS_INT_NM) != "") {
            $c.win.alert("금리연동탭은 변동금리시에만 입력합니다. 이자관련탭의 이자지급방법을 확인바랍니다.");
            tab_UsrInfo.setSelectedTabIndex(4);
            txb_INT_RT_DECSN_MISC_BAS_INT_NM.focus();
            return false;
        }
    }
    if ($c.stf.getObjectValue(cmb_SPLIT_REDMPT_TP_CD) != "" && $c.stf.getObjectValue(cmb_REDMPT_METHD_TP_CD).substring(0, 1) != "2") {
        $c.win.alert("상환방법탭은 분할상환시에만 입력합니다. 발행조건의 상환방법을 확인바랍니다.");
        tab_UsrInfo.setSelectedTabIndex(9);
        cmb_SPLIT_REDMPT_TP_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(ckb_BND_ISU_METHD_CD1) == "N" && $c.stf.getObjectValue(ckb_BND_ISU_METHD_CD2) == "N" &&
        $c.stf.getObjectValue(ckb_BND_ISU_METHD_CD3) == "N") {
        tab_UsrInfo.setSelectedTabIndex(1);
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "발행방법"));
        return false;
    }
    if ($c.stf.getObjectValue(cmb_ASST_SECUTIZ_TP_CD) == "" && $c.stf.getObjectValue(txb_SECUTIZ_ADM_INST_CD) != "") {
        $c.win.alert("유동화탭은 유동화 채권일 경우에만 입력합니다. 유동화채권 인지 확인바랍니다.");
        tab_UsrInfo.setSelectedTabIndex(9);
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_INT_RT_DECSN_MISC_BAS_INT_NM, 20, "기타기준금리")) {
        tab_UsrInfo.setSelectedTabIndex(4);
        //txb_INT_RT_DECSN_MISC_BAS_INT_NM.value = "";
        txb_INT_RT_DECSN_MISC_BAS_INT_NM.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_CFI_CD) == "") {
        tab_UsrInfo.setSelectedTabIndex(10);
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "채권의 CFI"));
        txb_CFI_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_BND_TP_CD) == "AB") {
        if ($c.stf.getObjectValue(txb_BND_CLSS_CD) == "") {
            $c.win.alert("채권분류코드가 없습니다.");
            txb_CFI_CD.focus();
            return false;
        }
    }
    if ($c.stf.getObjectValue(cmb_NUSUAL_BND_TP_CD) == "3" || $c.stf.getObjectValue(cmb_NUSUAL_BND_TP_CD) == "4") {
        $c.win.alert("ELS/DLS 는 수정할수 없습니다. ELS/DLS화면을 이용하세요.");
        cmb_NUSUAL_BND_TP_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_NUSUAL_BND_TP_CD) == "5") {
        $c.win.alert("전자단기사채 는 수정할수 없습니다. 전자단기사채화면을 이용하세요.");
        cmb_NUSUAL_BND_TP_CD.focus();
        return false;
    }

    //날짜포맷 체크
    if (fn_CheckDateObj(edt_ISU_DD, "발행일")) return false;
    if (fn_CheckDateObj(edt_REDMPT_DD, "상환일")) return false;
    if (fn_CheckDateObj(edt_SALE_DD, "선/후매출일")) return false;
    if (fn_CheckDateObj(edt_FST_INT_PAY_DD, "최초이자지급일")) return false;
    if (fn_CheckDateObj(edt_GRT_YD_STRT_DD, "보장수익률적용일")) return false;
    if (fn_CheckDateObj(edt_ADD_YD_STRT_DD, "추가수익률적용일")) return false;
    if (fn_CheckDateObj(edt_INT_RT_DECSN_BAS_DD, "최초표면이자율결정기준일")) return false;
    if (fn_CheckDateObj(edt_EXER_STRT_DD, "행사개시일")) return false;
    if (fn_CheckDateObj(edt_EXER_END_DD, "행사종료일")) return false;

    //이자지급주기 1규칙 2불규칙
    /*
    if (getObjectValue(cmb_INT_PAY_UNIT_MMS) == "1"){
    	if (getObjectValue(txb_INT_PAY_UNIT_MMS) == ""){
    		tab_UsrInfo.ActiveIndex =2;
    		alert( getMessageParam("MSG-A005", "이자지급주기") );
    		txb_INT_PAY_UNIT_MMS.focus();
    		return false;
    	}
    }
    */

    //이자계산주기 1규칙 2불규칙
    if ($c.stf.getObjectValue(cmb_INT_PAY_CALC_MMS) == "1") {
        if ($c.stf.getObjectValue(txb_INT_PAY_CALC_MMS) == "") {
            tab_UsrInfo.setSelectedTabIndex(2);
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "이자계산주기"));
            txb_INT_PAY_CALC_MMS.focus();
            return false;
        }
    }

    //상환방법: 영구채 선택시 휴무관련(원금) : 해당없음 선택이 원칙이나 선택사항이므로 경고문구만 띄운다.
    if ($c.stf.getObjectValue(cmb_REDMPT_METHD_TP_CD) == "3" && $c.stf.getObjectValue(cmb_BK_HOLDY_PRINC_PAY_DD_DECSN_CD) != "") {
        if (!window.confirm("상환방법이 '영구채'이며 휴무관련(원금)이 선택되었습니다.\n그래도 처리하시겠습니까?")) {
            return false;
        } else {
            return 1;
        }
    }
    if (!$c.stf.checkMaxLength(txa_NUSUAL_ISU_COND_CONTN, 60, "특이발행조건")) {
        //txb_ISU_ENG_ABBRV.value = "";
        txa_NUSUAL_ISU_COND_CONTN.focus();
        return false;
    }

    //마이너스입력체크
    if (fn_minusCheck(edt_COUPN_RT, "표면이자율") == "N") {
        return false;
    }
    if (fn_minusCheck(edt_SCBD_INT, "낙찰금리") == "N") {
        return false;
    }
    if (fn_minusCheck(edt_BK_HOLDY_DD_PRINC_ACRINT_RT, "원금 경과금리") == "N") {
        return false;
    }
    if (fn_minusCheck(edt_BK_HOLDY_DD_INT_CMP_ACRINT_RT, "이자 경과금리") == "N") {
        return false;
    }
    if (fn_minusCheck(edt_GRT_YD, "보장수익률") == "N") {
        return false;
    }
    if (fn_minusCheck(edt_ADD_YD, "추가수익률") == "N") {
        return false;
    }


    //CFI체크
    if ($c.stf.getObjectValue(cmb_cb_p_group) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_그룹"));
        cmb_cb_p_group.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_cb_p_attr_1) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_1차속성"));
        cmb_cb_p_attr_1.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_cb_p_attr_2) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_2차속성"));
        cmb_cb_p_attr_2.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_cb_p_attr_3) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_3차속성"));
        cmb_cb_p_attr_3.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_cb_p_attr_4) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_4차속성"));
        cmb_cb_p_attr_4.focus();
        return false;
    }
};





/********************************************** 
 * 함수명   : ins_chkRegisterStdCdCpBndInfo
 * 설명       : 채권 표준코등록 전   채권분류코드 체크
 ***********************************************/
scwin.ins_chkRegisterStdCdCpBndInfo = function() {
    dts_detail.setCellData(dts_detail.getRowPosition(), "CRDUSTATUS", $c.ut.cGetToday("yyyymmddhhmmss"));
    dts_CreditValuList.setCellData(dts_CreditValuList.getRowPosition(), "CRDUSTATUS", $c.ut.cGetToday("yyyymmddhhmmss"));
    dts_AsstList.setCellData(dts_AsstList.getRowPosition(), "CRDUSTATUS", $c.ut.cGetToday("yyyymmddhhmmss"));
    trs_chksave.Action = "/StdCdBndInfoAction.do?method=chkRegisterStdCdBndInfo" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    trs_chksave.KeyName = "toinb_dataid4";
    trs_chksave.KeyValue = "JSP(O:pReturnOut=dts_Rst,I:pInput=dts_detail)";
    trs_chksave.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm + ",EMAIL=" + js_email;
    trs_chksave.Post();
};


/********************************************** 
 * 함수명   : ins_modify
 * 설명       : 채권 수정 한다.
 ***********************************************/
scwin.ins_modify = function() {
    if (scwin.fn_formCheck() == false) return;
    dts_detail.setCellData(dts_detail.getRowPosition(), "CRDUSTATUS", $c.ut.cGetToday("yyyymmddhhmmss"));
    dts_CreditValuList.setCellData(dts_CreditValuList.getRowPosition(), "CRDUSTATUS", $c.ut.cGetToday("yyyymmddhhmmss"));
    dts_AsstList.setCellData(dts_AsstList.getRowPosition(), "CRDUSTATUS", $c.ut.cGetToday("yyyymmddhhmmss"));
    for (var i = 1; i <= dts_callList.getTotalRow(); i++) {
        dts_callList.setCellData(i, "CRDUSTATUS", $c.ut.cGetToday("yyyymmddhhmmss"));
    }
    for (var i = 1; i <= dts_putList.getTotalRow(); i++) {
        dts_putList.setCellData(i, "CRDUSTATUS", $c.ut.cGetToday("yyyymmddhhmmss"));
    }
    for (var i = 1; i <= dts_BND_PAY_INT.getTotalRow(); i++) {
        dts_BND_PAY_INT.setCellData(i, "CRDUSTATUS", $c.ut.cGetToday("yyyymmddhhmmss"));
    }
    trs_save.Action = "/StdCdBndInfoAction.do?method=modifyStdCdBndInfo" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03 + "&CP_BND_TP_CD=" + dts_List.getCellData(dts_List.getRowPosition(), "CP_BND_TP_CD");
    trs_save.KeyName = "toinb_dataid4";
    trs_save.KeyValue = "JSP(O:pReturnOut=dts_Rst2,I:pInput=dts_detail,I:pInput1=dts_callList,I:pInput2=dts_putList,I:pInput3=dts_CreditValuList,I:pInput4=dts_AsstList,I:pInput5=dts_BND_PAY_INT)";
    trs_save.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm + ",EMAIL=" + js_email;
    trs_save.Post();
};


/********************************************** 
 * 함수명   : ins_remove
 * 설명       :채권  삭제처리한다.
 ***********************************************/
scwin.ins_remove = function() {

    //dts_ListDelete.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    dts_ListDelete.insertRow();
    dts_ListDelete.setCellData(1, "STD_CD", txb_STD_CD.getValue());
    dts_ListDelete.setCellData(1, "ISU_NM", txb_ISU_NM.getValue());
    dts_ListDelete.setCellData(1, "CHG_RSN", txb_DEL_RSN.getValue());
    dts_ListDelete.setCellData(1, "UNQ_ISU_NM", txb_UNQ_ISU_NM.getValue());
    dts_ListDelete.setCellData(1, "ISUR_CD", txb_ISUR_CD.getValue());
    dts_ListDelete.setCellData(1, "ISU_DD", edt_ISU_DD.getValue());
    dts_ListDelete.setCellData(1, "MUNIBND_TP_CD", $c.stf.getObjectValue(cmb_MUNIBND_TP_CD));
    dts_ListDelete.setCellData(1, "BND_TP_CD", $c.stf.getObjectValue(cmb_BND_TP_CD));
    dts_ListDelete.setCellData(1, "INT_PAY_METHD_CD", $c.stf.getObjectValue(cmb_INT_PAY_METHD_CD));
    dts_ListDelete.setCellData(1, "NUSUAL_BND_TP_CD", $c.stf.getObjectValue(cmb_NUSUAL_BND_TP_CD));
    trs_remove.Action = "/StdCdBndInfoAction.do?method=removeStdCdBndInfo" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
    trs_remove.KeyName = "toinb_dataid4";
    trs_remove.KeyValue = "JSP(I:pInput=dts_ListDelete)";
    trs_remove.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm + ",EMAIL=" + js_email;
    trs_remove.Post();
};



