/********************************************** 
 * 함수명   : fn_BND_ISU_METHD_CD
 * 설명       : 발행방법 정의한다. 100 : 공모-간접발행, 010 : 공모-직접발행, 001 : 사모
 ***********************************************/
scwin.fn_BND_ISU_METHD_CD = function() {
    var BND_ISU_METHD_CD1 = $c.stf.getObjectValue(ckb_BND_ISU_METHD_CD1);
    var BND_ISU_METHD_CD2 = $c.stf.getObjectValue(ckb_BND_ISU_METHD_CD2);
    var BND_ISU_METHD_CD3 = $c.stf.getObjectValue(ckb_BND_ISU_METHD_CD3);
    if (BND_ISU_METHD_CD1 == "Y") {
        BND_ISU_METHD_CD1 = "1";
    } else {
        BND_ISU_METHD_CD1 = "0";
    }
    if (BND_ISU_METHD_CD2 == "Y") {
        BND_ISU_METHD_CD2 = "1";
    } else {
        BND_ISU_METHD_CD2 = "0";
    }
    if (BND_ISU_METHD_CD3 == "Y") {
        BND_ISU_METHD_CD3 = "1";
    } else {
        BND_ISU_METHD_CD3 = "0";
    }
    $c.stf.setObjectValue(txb_BND_ISU_METHD_CD, BND_ISU_METHD_CD1 + BND_ISU_METHD_CD2 + BND_ISU_METHD_CD3);
};


/********************************************** 
 * 함수명   : fn_set_BND_ISU_METHD_CD
 * 설명       : 발행방법 정의한다. 100 : 공모-간접발행, 010 : 공모-직접발행, 001 : 사모
 ***********************************************/
scwin.fn_set_BND_ISU_METHD_CD = function() {
    var BND_ISU_METHD_CD = $c.stf.getObjectValue(txb_BND_ISU_METHD_CD);
    $c.stf.setObjectValue(ckb_BND_ISU_METHD_CD1, "N");
    $c.stf.setObjectValue(ckb_BND_ISU_METHD_CD2, "N");
    $c.stf.setObjectValue(ckb_BND_ISU_METHD_CD3, "N");
    if (BND_ISU_METHD_CD == "") return;
    var BND_ISU_METHD_CD1 = BND_ISU_METHD_CD.substring(0, 1);
    var BND_ISU_METHD_CD2 = BND_ISU_METHD_CD.substring(1, 2);
    var BND_ISU_METHD_CD3 = BND_ISU_METHD_CD.substring(2, 3);
    if (BND_ISU_METHD_CD1 == "1") {
        $c.stf.setObjectValue(ckb_BND_ISU_METHD_CD1, "Y");
    } else {
        $c.stf.setObjectValue(ckb_BND_ISU_METHD_CD1, "N");
    }
    if (BND_ISU_METHD_CD2 == "1") {
        $c.stf.setObjectValue(ckb_BND_ISU_METHD_CD2, "Y");
    } else {
        $c.stf.setObjectValue(ckb_BND_ISU_METHD_CD2, "N");
    }
    if (BND_ISU_METHD_CD3 == "1") {
        $c.stf.setObjectValue(ckb_BND_ISU_METHD_CD3, "Y");
    } else {
        $c.stf.setObjectValue(ckb_BND_ISU_METHD_CD3, "N");
    }
};
scwin.fn_set_fn_GetParam = function(vparam1) {
    txb_param1.setValue(vparam1);
    txb_param2.setValue("");
    fn_GetPar = fn_GetParam;
};
