};
scwin.dts_detail_OnLoadCompleted = function(rowcount) {
    if (rowcount > 0) {
        fn_CtrlBtn_temp("update");
        var CFI_CD = dts_detail.getCellData(dts_detail.rowpositon, "CFI_CD");
        var SIMSA_YN = dts_detail.getCellData(dts_detail.rowpositon, "SIMSA_YN");
        var LIST_STAT_CD = dts_detail.getCellData(dts_detail.rowpositon, "LIST_STAT_CD");
        //set_Change("ECVTCN") ;
        scwin.fn_set_Change(CFI_CD);
        scwin.fn_setBndView(SIMSA_YN, LIST_STAT_CD);
        scwin.fn_COUPN_RT_DECSN_BAS_INT_CDChage();
        if (dts_detail.getCellData(dts_detail.rowpositon, "CASH_PAY_YN") == "Y") {
            $c.stf.setObjectValue(ckb_CASH_PAY_YN, "Y");
        } else {
            $c.stf.setObjectValue(ckb_CASH_PAY_YN, "N");
        }
        if (dts_detail.getCellData(dts_detail.rowpositon, "SB_PAY_YN") == "Y") {
            $c.stf.setObjectValue(ckb_SB_PAY_YN, "Y");
        } else {
            $c.stf.setObjectValue(ckb_SB_PAY_YN, "N");
        }
        scwin.fn_set_BND_ISU_METHD_CD();

        //발행전국채거래 활성/비활성
        if (txb_ISUR_CD.getValue() == "GB035") {
            cmb_PRESALE_GOVBND_TRD_TP_CD.setDisabled(false);
            cmb_PRESALE_GOVBND_TRD_TP_CD.disableBackColor = '#ffffff';
        } else {
            cmb_PRESALE_GOVBND_TRD_TP_CD.setDisabled(true);
            cmb_PRESALE_GOVBND_TRD_TP_CD.disableBackColor = '#b9d4f7';
        }
    } else {
        fn_CtrlBtn_temp("no_data");
    }
    tab_UsrInfo.setSelectedTabIndex(1);
};
